"""Factory module"""
from __future__ import annotations

from typing import TYPE_CHECKING

from taf.ul.oran_mplane.core.libraries.ncclient_wrapper import NcclientWrapper
from taf.ul.oran_mplane.core.libraries.netconf_client_wrapper import NetconfClientWrapper

if TYPE_CHECKING:
    from netconf_client.ncclient import Manager as NetconfClientManager
    from ncclient import manager as NcclientManager


class LibrariesFactory:
    """LibrariesFactoryFactory class"""

    def __init__(self, protocol: str, manager: NetconfClientManager | NcclientManager):
        self.protocol = protocol
        self.manager = manager

    def create(self):
        """return appropriate class"""
        libraries = {"ssh": NcclientWrapper, "tls": NetconfClientWrapper}
        return libraries[self.protocol](self.manager)
